mapper.select:
/* selectTlphonDscsnList - Lee MS */
SELECT A.DSCSN_YMD AS DSCSN_YMD, /* 상담일자 */ A.TRPR_INFO_NO AS TRPR_INFO_NO, /* 대상자정보번호*/ C##RG.DEC_B64(B.TRPR_NM_ENCPT) AS TRPR_NM, /* 대상자명 */ B.TRPR_BRTH_YMD AS TRPR_BRTH_YMD, /* 생년월일 */ B.SXDC_SE_CD AS SXDC_SE_CD, /* 성별 */ B.ZIP AS ZIP, /* 우편번호 */ B.PST_ADDR AS PST_ADDR, /* 주소 */ B.DADDR AS DADDR, /* 상세주소 */ C##RG.DEC_B64(C.FLNM_ENCPT) AS FLNM, /* 담당자명 */ D.INST_NM AS INST_NM, /* 기관명 */ D.RPRS_TELNO AS RPRS_TELNO, /* 대표전화번호 */ D.BPLC_ZIP AS BPLC_ZIP, /* 기간우편번호 */ D.BPLC_PST_ADDR AS BPLC_PST_ADDR, /* 기간주소 */ D.BPLC_DADDR AS BPLC_DADDR, /* 기간상세주소 */ A.CO13_MNG_NO AS CO13_MNG_NO /*1388상담관리번호 */ FROM ACA140 A, SEA200 B, SCA100 C, SAA000 D /* 대상자(B), 종사자(C), 통합기관(D) */ WHERE A.TRPR_INFO_NO = B.TRPR_INFO_NO AND A.PIC_NO = C.ENFSN_NO AND A.INST_NO = D.INST_NO AND A.DSCSN_YMD >= #{BGNG_YMD} AND A.DSCSN_YMD <= #{END_YMD} AND (A.INST_NO IN
--20230629 이승재 - 권한쿼리
#{item}
OR A.LINK_INST_NO IN
#{item}
)
AND A.PIC_NO = #{ENFSN_NO}
--20230629 이승재 - 권한쿼리 종료
AND C##RG.DEC_B64(B.TRPR_NM_ENCPT) LIKE '%'||#{TRPR_NM}||'%'
